package co.com.segurosbolivar.config;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.web.servlet.FilterRegistrationBean; import org.springframework.context.annotation.*; import org.springframework.http.*; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException;
@Configuration public class SecurityConfig { @Bean FilterRegistrationBean<ApiKeyFilter> apiKeyFilter(@Value("${app.api-key}")String key){var b=new FilterRegistrationBean<ApiKeyFilter>();b.setFilter(new ApiKeyFilter(key));b.addUrlPatterns("/*");b.setOrder(1);return b;} static class ApiKeyFilter extends OncePerRequestFilter {private final String key;ApiKeyFilter(String k){key=k;} protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{if(key.equals(req.getHeader("x-api-key")))chain.doFilter(req,res);else{res.setStatus(HttpStatus.UNAUTHORIZED.value());res.setContentType("application/json");res.getWriter().write("{\"error\":\"API Key inválida o ausente\"}");}}} }
